    FIRE_COMBUSTION = "Используй, когда огненные заклинания будут попадать и есть безопасное время для чтения. Согласуй с задачей на взрывной урон; не удерживай так долго, чтобы потерять целое применение.",
    FIRE_MIRRORS = "На 80-м применяй в безопасном окне усиления. Временное управление угрозой не равно постоянному обнулению: планируй окончание копий и не игнорируй танка.",
    FIRE_MOVEMENT = "Двигайся только насколько нужно; используй доступную мгновенную Глыбу, своевременную бомбу или Огненный взрыв по ситуации. Не трать глобальное восстановление ценой более сильного мгновенного действия или раннего обновления бомбы.",
    FIRE_EVOCATION = "Планируй восстановление до полного опустошения. Поддерживай в безопасном окне достаточной длины: прерывание и движение теряют восстановление. Камни маны планируй отдельным ресурсом.",
    FIRE_INVISIBILITY = "С 68-го заранее учитывай время исчезновения и угрозу. Урон может помешать исчезновению; прекрати чтение и соблюдай механику. Это не мгновенная неуязвимость.",
    FIRE_ICE_BLOCK = "Экстренная неуязвимость или снятие назначенного эффекта. В глыбе нельзя наносить урон; снимай, когда безопасно, и учитывай Переохлаждение. Не все механики решаются этой кнопкой.",
    FIRE_BLINK = "Перемещайся в известную безопасную точку, не в опасную область и не сквозь танка. Проверь восстановление до выбора рискованной позиции для чтения.",
    FIRE_COUNTERSPELL = "Прерывай назначенное опасное заклинание. Дополнительный Шар не компенсирует пропущенное прерывание. Некоторые боссы невосприимчивы: следуй плану боя.",
    FIRE_CURSE = "Вовремя снимай назначенные проклятия, когда безопасно. Не снимай эффекты, которые должны оставаться по механике; следи за группой и движением.",
    FIRE_CONSUMABLES = "Выбирай один настой ИЛИ совместимые боевой/защитный эликсиры, одну еду и подходящее зелье. Настой и эликсиры не складываются. Зелье перед боем и одно в бою требуют точного времени и обычных ограничений 3.3.5a на сервере.",
    FIRE_MANA_GEM = "До боя создай и возьми подходящий камень маны; не жди полного опустошения. У камней, зелий и особых расходников есть взаимодействия восстановления: проверь их до планирования совместного применения.",
    FIRE_FLASK = "Вариант настоя заклинателя: сохраняется после смерти и заменяет эликсиры. Проверь уровень и доступность эпохи до покупки.",
    FIRE_ELIXIR = "Эликсир силы заклинаний вместо настоя, не дополнительный бонус поверх него. После смерти обнови.",
    FIRE_FOOD = "Еда заклинателя: поддерживай сытость. Еду на меткость бери только под реальный недостаток; пищевые усиления не складываются.",
    FIRE_FOOD_MANA = "Еда на восстановление маны для ограниченного маной боя 60-го уровня. Это не универсальный максимум урона.",
    FIRE_SPEED_POTION = "Под безопасное окно чтения/усилений: движение и прерывание тратят эффект зря. Делит ограничения зелий с зельем маны.",
    FIRE_MANA_POTION = "Альтернатива ради маны, если предотвращает простой; не дополнительное зелье сверх боевого ограничения.",
    FIRE_ENHANCEMENTS_60 = "Предпочитай силу заклинаний на оружии и полезные чары заклинателя. В Classic не предполагаются гнёзда/мета. Редкие поздние рецепты могут быть закрыты прогрессией сервера.",
    FIRE_ENHANCEMENTS_70 = "Чары заклинателя 70-го уровня, камни силы заклинаний и мета для заклинателя. Проверяй профессию, репутацию и уровень вещи: механика Wrath не открывает автоматически рецепты Wrath.",
    FIRE_ENHANCEMENTS_80 = "Добери нужную меткость, затем предпочитай силу заклинаний. Сравнивай гибриды сила/скорость ради полезных бонусов гнёзд и выполни минимальное синее условие мета. Ранние этапы — редкие камни; эпические указаны с Колизея.",
    FIRE_ENCHANT_REQUIREMENTS = "Усиления головы/плеч требуют соответствующей репутации. Нити — подходящих поножей, пряжка — подходящего пояса. Профессиональные варианты заменяют обычные чары. Перед переносом чар одноручной сборки на посох отдельно проверь применимость.",
    FIRE_ENCHANTS = "Вариант чар для слота заклинателя: проверь доступность рецепта и требования вещи. Скорость движения может быть полезнее небольшой прибавки неподвижного урона.",
    FIRE_GEMS = "Вариант корректировки: сила заклинаний, сила/меткость или сила/скорость под свой кап и бонус гнезда. Фиолетовые подходят под синее условие мета; не заполняй автоматически все синие гнёзда.",
    FIRE_META = "Мета на критический урон заклинателя: нужно не менее двух синих камней. Выполни точное условие подсказки; не переноси другое условие паладинского мета.",
    FIRE_GEAR_DRAFT = "Кандидаты заклинателя для этапа, не подтверждённый BiS. Исторический порядок Classic/TBC требует проверки под 3.3.5a; профессии, невосприимчивость врага и меткость полного комплекта меняют выбор. Сохранение прежних вещей не означает отсутствия промежуточных улучшений.",
    RET_CAPS_60 = "Против рейдового босса 63-го уровня: цель — 8% меткости ближнего боя и 26 суммарного мастерства. Человек с мечом или дробящим получает 3 мастерства: из остальных источников нужно 23. Символ накапливающейся печати здесь неприменим. Для врагов меньшего уровня в подземельях цели отличаются: не покупай рейтинг под босса, с которым не сражаешься.",
    RET_CAPS_70 = "Против босса 73-го уровня: цель — 8% меткости ближнего боя и 26 суммарного мастерства по правилам Wrath, а не исторический кап TBC. Человеческая специализация мечей/дробящего даёт 3 мастерства, действующая накапливающаяся печать с символом — 10: остаётся 13 из других источников. Печать для нескольких целей или топор убирают соответствующий бонус.",
    RET_CAPS_80 = "Против босса 83-го уровня: 8% меткости ближнего боя — примерно 263 рейтинга без группового бонуса или 230 с надёжно действующим 1% Боевого духа. Цель — 26 мастерства: меч/дробящее человека и действующая печать с символом оставляют 13, примерно 107 рейтинга. С топором и этим символом остаётся 16, примерно 132 рейтинга. Не вычитай неактивные бонусы.",
    RET_STATS_GEAR_CHOICE = "Оценивай комплект, а не одну зелёную цифру: урон/скорость оружия, капы, бонусы комплектов и эффекты аксессуаров работают вместе. Не ломай полезный комплект только ради уровня предмета. Меткость ближнего боя не гарантирует попадания заклинаний; не добирай их кап камнями в ущерб основным характеристикам.",
    RET_PROFESSIONS_60 = "На 60-м ремесленные профессии дают доступ к передаваемой экипировке, но изготовленный предмет не обязательно требует профессию для ношения. Инженерия даёт полезные инструменты под бой. Проверяй конкретное требование, не считай весь крафт привязанным к профессии.",
    RET_PROFESSIONS_70 = "На 70-м рекомендуемые инженерные очки требуют Инженерное дело 350 для ношения. Без него оставь предыдущий пригодный шлем до сравнения с рейдовыми заменами. Специализации кузнеца, гнёзда и доступ к расходникам зависят от прогрессии: проверь доступность до траты материалов.",
    RET_PROFESSIONS_80 = "На 80-м инженерия даёт усиление перчаток для взрывного урона и средства передвижения; ювелирное и кузнечное дело — профессиональные бонусы характеристик. Чары колец, кожевнические усиления запястий и портняжные эффекты — профессиональные альтернативы, а не дополнительные складывающиеся чары. Сравнивай полный набор бонусов с учётом выживания и движения.",
    GEAR_ENGINEERING_350 = "Для ношения требуется Инженерное дело 350. Без него оставь пригодный предыдущий шлем: это не безусловная замена.",
    GEAR_REP_BROOD = "Требуется превознесение с Родом Ноздорму и соответствующий этап получения кольца.",
    GEAR_REP_CONSORTIUM = "Требуется превознесение с Консорциумом: покупка за репутацию не равна немедленному дорейдовому дропу.",
    GEAR_REP_SHATAR = "Требуется превознесение с Ша'тар.",
