    RET_OVERVIEW = "PvE-урон в ближнем бою с двуручным оружием. Даже на 60/70 используются таланты и способности 3.3.5a, а не исторические механики Vanilla/TBC.",
    RET_LEVEL_60 = "60-й уровень: 51 очко талантов. Основа — глубокая ветка «Воздаяние»; способности, изучаемые позже, недоступны.",
    RET_LEVEL_70 = "70-й уровень: 61 очко талантов. Для долгого боя с одной целью подходит накапливающаяся печать; для коротких боёв с группами — удары по нескольким целям.",
    RET_LEVEL_80 = "80-й уровень: 71 очко талантов. Бонусы комплектов могут менять приоритет способностей. Списки экипировки пока черновые, не подтверждённый BiS.",
    RET_SUPPORT = "По возможности атакуй сзади. Согласуй благословения и правосудие с рейдом; помогай защитными способностями, не нарушая механики боя. Расовая искусность человека зависит от типа оружия.",
    RET_STATS_HIT = "Сначала устрани промахи специальных атак ближнего боя по выбранной цели. Обычная цель против рейдового босса — 8% суммарной меткости; учти групповые усиления. Это не кап всех заклинаний.",
    RET_STATS_EXPERTISE = "Для ударов сзади ориентир против босса — 26 искусности. Учти расовые бонусы и символ активной печати до набора рейтинга; фронтальные парирования лучше исключить позицией.",
    RET_STATS_STRENGTH = "Сила — основной источник урона после разумного достижения меткости и искусности. Сила заклинаний и пробивание брони не являются универсальной целью для ретри.",
    RET_STATS_SECONDARY = "Крит, скорость, ловкость и сила атаки зависят от всего комплекта. Сравнивай вещи с правильными уровнем, усилениями и сет-бонусами; пересчёт рейтинга для 80 не подходит для 60/70.",
    RET_TALENT_60 = "Черновая раскладка 0/0/51. Сохраняй основу урона и восстановления маны в «Воздаянии»; вспомогательные таланты зависят от состава рейда.",
    RET_TALENT_70 = "Черновая раскладка 5/5/51. Дополнительные очки усиливают печати и силу; это дерево WotLK на 70-м уровне.",
    RET_TALENT_80 = "Черновая раскладка 11/5/55 с рейдовой поддержкой. Альтернативы зависят от состава. Отображение не распределяет таланты персонажа.",
    RET_GLYPH_60 = "На 60-м доступны два больших символа, не три. Выбирай эффекты доступных способностей; символ накапливающейся печати не подходит до изучения этой печати.",
    RET_GLYPH_70 = "На 70-м доступны два больших символа. Кандидаты — усиление правосудия и искусность от печати; бонус искусности действует только при нужной активной печати.",
    RET_GLYPH_80 = "На 80-м доступны три больших символа. Кандидаты — правосудие, искусность от печати и освящение. Символы, добавленные только в современном Classic, исключены.",
    ROTATION_PREPARATION = "Подготовка и начало боя",
    ROTATION_SINGLE = "Одна цель",
    ROTATION_AOE = "Несколько целей",
    ROTATION_UTILITY = "Выживание и помощь рейду",
    RET_ROTATION_NOTE = "На каждом свободном глобальном восстановлении выбирай доступное действие под ситуацию. Это приоритет, а не жёсткая последовательность и не автоматическая ротация.",
    RET_ROTATION_BASE_PRIORITY = "База без 2T10: Правосудие > Молот гнева ниже 20% здоровья > Удар воина Света > Божественная буря > Освящение > мгновенный Экзорцизм > Гнев небес против нежити/демонов. Не стой без действия, ожидая более высокого пункта. Оружие, комплекты и длительность боя меняют близкие решения.",
    RET_ROTATION_2T10 = "Только с надетыми двумя предметами ретри-комплекта T10: атаки ближнего боя могут сбрасывать восстановление Божественной бури. Подними её в начало приоритета, чтобы не терять сбросы. Без бонуса вернись к базовому порядку: само открытие ЦЛК бонуса не даёт.",
    RET_POSITIONING = "Держись за спиной цели в ближнем бою, не прерывай автоатаки и быстро переключайся по заданию. Не продолжай ротацию ценой смертельной механики. Провокации не используй ради урона.",
    RET_OPENER_VENGEANCE = "До боя включи накапливающуюся печать. Войди в ближний бой вместе с танком, начни автоатаки и Правосудие, набери пять эффектов на основной цели. Не переключай печати постоянно и не набирай стаки на почти погибших врагах.",
    RET_OPENER_COMMAND = "На 60-м накапливающаяся печать ещё не изучена: начни с талантовой печати для нескольких целей. Дождись танка, включи автоатаки и Правосудие, затем следуй приоритету одной цели. Seal twisting из TBC для механики 3.3.5a не нужен.",
    RET_BLESSINGS = "Согласуй Королей/Могущество и ауру с рейдом: одинаковые усиления не складываются. Отключи Праведное неистовство перед нанесением урона.",
    RET_HOLY_WRATH = "Последний заполнитель только против нежити и демонов. На других типах не трать глобальное восстановление. Оглушение может помешать контролю группы.",
    RET_AOE_STORM = "Используй рано с несколькими безопасными целями в ближнем бою и печатью для нескольких целей. Не ломай контроль и не забирай группу у танка.",
    RET_AOE_CONSECRATION = "Размещай под устойчиво стоящей группой. Сохраняй Правосудие ради маны и основной цели; пропускай дорогой эффект, если враги уйдут или маны мало.",
    RET_PROTECTION = "Включай снижение урона перед предсказуемым уроном. Божественный щит — отдельная экстренная мера: учитывай Воздержанность и штраф к урону.",
    RET_FREEDOM = "Снимай ограничения движения с себя или назначенного союзника, если механика это допускает. Это не замена правильной позиции.",
    RET_SALVATION = "Заранее снижай угрозу при приближении к танку. Это не провокация и не мгновенное обнуление угрозы.",
    RET_CLEANSE = "Снимай магию, яды и болезни по назначению и когда безопасно. Не рассеивай эффекты, которые должны оставаться; экстренная помощь важнее жёсткой ротации.",
